SELECT id, post_id, reporter_member_id, reason, detail, status, created_at
  FROM community_report
 WHERE post_id = #{postId}
   AND reporter_member_id = #{reporterMemberId}

SELECT CASE WHEN COUNT(1) > 0 THEN 'Y' ELSE 'N' END AS EXISTS_YN
  FROM community_report
 WHERE post_id = #{postId}
   AND reporter_member_id = #{reporterMemberId}
